D.ClientTexts.Currency[402]={Name={["43701b869f510bbb:12"]="铁掌徽记"},Description={["a9625bf1c6919a76:129"]="代表你受到了烹饪世家——铁掌家族的嘉许。可在半山市集的库房管理员处兑换烹饪配料和其它物品。"}}
D.ClientTexts.Currency[416]={Name={["370d5ebeb37cb8a3:18"]="世界之树的印记"},Description={["1a4bfbd679f2d09f:91"]="由海加尔守护者授予。可以用来购买进攻火焰之地的补给。"}}
D.ClientTexts.Currency[483]={Name={["ef580005c3f471ac:17"]="竞技场征服点数变量"}}
D.ClientTexts.Currency[484]={Name={["0e2d109782f1feee:19"]="评级战场征服点数变量"}}
D.ClientTexts.Currency[515]={Name={["a02e72cec5210b27:19"]="暗月奖券"},Description={["dffd29542ffbc197:54"]="在暗月马戏团的游戏中获胜或完成工作人员交付的任务后获得。"}}
D.ClientTexts.Currency[614]={Name={["2d39f9ca2814d317:14"]="黑暗之尘"},Description={["cb7200030b89df54:78"]="由死亡之翼的灭世之力凝聚而成，其中蕴含的黑暗能量可以强化威力骇人的魔法。"}}
D.ClientTexts.Currency[615]={Name={["85350c73e9475cba:27"]="死亡之翼的堕落精华"},Description={["664056b4a9b1e44b:80"]="从死亡之翼的身躯中抽离而出的黑暗能量，用以催动最为恐怖的咒术。"}}
D.ClientTexts.Currency[676]={Name={["0d39d63067c5b3b9:27"]="熊猫人考古碎片"}}
D.ClientTexts.Currency[677]={Name={["006f503f261857ea:23"]="魔古考古碎片"}}
D.ClientTexts.Currency[692]={Name={["b095d588d972d60d:20"]="随机战场征服点数变量"}}
D.ClientTexts.Currency[697]={Name={["a6f909bd6d9b1700:23"]="长者的好运符"},Description={["4a4c08ae73ae2ab3:172"]="长者好运符的拥有者在战胜魔古山宝库、恐惧之心、永春台中的首领，以及怒之煞或萨莱斯的兵团后有机会使用一枚硬币来赢取额外的奖励。"}}
D.ClientTexts.Currency[698]={Name={["8702ef6b56356900:22"]="珠宝禅师的奖章"},Description={["faa9026dda9f8fbe:131"]="授予技艺最精湛的珠宝名匠，这些奖章可以用来兑换稀有的珠宝加工图鉴和美丽的蛟眼石。"}}
D.ClientTexts.Currency[738]={Name={["fde8d53f5f3add5c:24"]="次级好运护符"},Description={["8fb3acdac6e2070b:177"]="携带次级好运护符能带来好运，并能最终兑换战火徽记，使玩家在赢得团队副本战斗后有机会使用一枚硬币来赢取额外的奖励。"}}
D.ClientTexts.Currency[752]={Name={["4d30bdcc04cd892d:14"]="魔古命运符文"},Description={["dd3e43e62a5883d9:119"]="魔古命运符文的拥有者也许能在战胜雷电王座中的首领后，以及在战胜纳拉克或乌达斯塔后获得额外的战利品奖励。"}}
D.ClientTexts.Currency[754]={Name={["596314a489d361c5:25"]="螳螂妖考古碎片"}}
D.ClientTexts.Currency[776]={Name={["80bd4d4b1529f402:13"]="战火徽记"},Description={["52d6c42e3d101855:131"]="拥有战火徽记的幸运儿有机会在决战奥格瑞玛、天神试炼和斡耳朵圣殿中用一枚徽记换取一份额外奖励。"}}
D.ClientTexts.Currency[777]={Name={["06a20594c8fd72f7:12"]="永恒铸币"},Description={["3423689e36ef9f11:155"]="你在恍惚中感觉到这枚铸币过去与未来的拥有者的手指拂过你的掌心，仿佛时间的界限被模糊了。你可以用它在永恒岛上换取强大且多样性的奖励。"}}
D.ClientTexts.Currency[789]={Name={["a94e63177c9f7170:10"]="染血铸币"},Description={["fa1d04f025f1275b:72"]="从死于永恒岛周围迷雾中的敌人身上摸来的铸币。"}}
D.ClientTexts.Currency[810]={Name={["624ad8ce336830b7:17"]="黑铁碎片"},Description={["20b5df08cff05825:60"]="从钢铁部落入侵者碎裂的护甲和武器中翻检出的金属碎片。"}}
D.ClientTexts.Currency[821]={Name={["a2473963fc4c9ebc:31"]="德拉诺氏族考古碎片"}}
D.ClientTexts.Currency[823]={Name={["2d1b83519a3f6f8a:13"]=S[7773]},Description={["3379425eab53aa0d:87"]="作为一个失落文明的古老遗产，埃匹希斯水晶蕴藏着难以想象的强大魔力。"}}
D.ClientTexts.Currency[824]={Name={["15ba9e45158b2a42:17"]="要塞物资"},Description={["717387e0d60cc689:45"]="赚取资源以建造和扩大你的要塞。"}}
