D.ClientTexts.Currency[897]={Name={["20d33cb9ce7cbbb6:6"]="血腥徽记"}}
D.ClientTexts.Currency[910]={Name={["9cf0fa6e82081809:22"]=S[10801]},Description={["d7cb7e72b6305707:56"]="让你可通过炼金实验室获得新的炼金配方。"}}
D.ClientTexts.Currency[944]={Name={["2fd794a7d3df4c22:16"]="神器碎片"},Description={["430232838a77bc30:64"]="一块阿什兰失落神器的小碎片，被悬槌食人魔视为珍宝。"}}
D.ClientTexts.Currency[980]={Name={["be061fb4955636df:14"]="肮脏的铁币"},Description={["94c32922b685c119:53"]="或许它们比表面上看起来的要珍贵得多。"}}
D.ClientTexts.Currency[994]={Name={["00a28eb5bcca2de0:18"]="钢化命运印记"},Description={["f53413e11f5918c6:87"]="扭曲命运，可给你一次在悬槌堡或黑石铸造厂团队副本获得额外宝物的机会。"}}
D.ClientTexts.Currency[999]={Name={["f36b17d4632f2397:24"]=S[10806]},Description={["ea6581e2a94f2f45:58"]="可让你从裁缝店获得新的裁缝配方。"}}
D.ClientTexts.Currency[1008]={Name={["9a51811094e8bfed:28"]=S[10802]},Description={["5fe806bc041efa03:41"]="可让你获得新的珠宝加工配方。"}}
D.ClientTexts.Currency[1017]={Name={["81b1c6510fa7e560:29"]=S[10798]},Description={["be19304945059dae:53"]="可让你从制革厂获得新的制皮配方。"}}
D.ClientTexts.Currency[1020]={Name={["da51c1abc1c2d606:28"]=S[10807]},Description={["4380b257d0d09e1c:41"]="可让你获得新的锻造配方。"}}
D.ClientTexts.Currency[1101]={Name={["0b8899093711d332:3"]="原油"},Description={["dbd60c6a3f364323:58"]="主要产于塔纳安丛林的原油，可以作为海军行动的燃油。"}}
D.ClientTexts.Currency[1129]={Name={["470e40620d9b133b:20"]="既定命运印记"},Description={["d0451e0969131458:94"]="扭转命运，可给你一次在地狱火堡垒或德拉诺史诗地下城获得额外宝物的机会。"}}
D.ClientTexts.Currency[1149]={Name={["772b497eae03c39b:12"]="盲目之眼"},Description={["6b1870c5f1f16ae4:100"]="一枚粗糙的手工硬币，上面有一个类似肯瑞托的徽记，但有一个最大的不同点：那个眼睛是闭着的。"}}
D.ClientTexts.Currency[1154]={Name={["e69860009bfed8a9:12"]="暗影币"},Description={["1619149e79f9c61b:71"]="在扒手以及类似阶层中广受欢迎。可以在达拉然的下水道中使用。"}}
D.ClientTexts.Currency[1155]={Name={["8af6cda4651981bf:11"]="远古魔力"},Description={["8aaaf75cd9949b79:54"]="来自苏拉玛地下古代魔网的浓缩魔力。"}}
D.ClientTexts.Currency[1166]={Name={["0fc847ea0a76134f:15"]="时空扭曲徽章"},Description={["ab5e15052bba0b42:83"]=S[7129]}}
D.ClientTexts.Currency[1171]={Name={["1b20a353d388cd8c:17"]="神器知识"},Description={["4de0102380b93468:44"]="提高你获得神器能量的速度。"}}
D.ClientTexts.Currency[1172]={Name={["c7965e1d63545820:28"]="上层精灵考古碎片"}}
D.ClientTexts.Currency[1173]={Name={["4e08da21a4f64398:37"]="至高岭牛头人考古碎片"}}
D.ClientTexts.Currency[1174]={Name={["ed0b4d4625803d95:26"]="恶魔考古碎片"}}
D.ClientTexts.Currency[1191]={Name={["108d568925a68904:5"]="勇气点数"},Description={["1e1c0623c28c31fa:111"]="用于强化来自地狱火堡垒、塔纳安丛林、德拉诺地下城以及强大的制造物品能力的货币。"}}
D.ClientTexts.Currency[1220]={Name={["54286fbc6a0b9d17:14"]="职业大厅资源"},Description={["3d60585ce62fb359:68"]="用来招募部队，执行任务和研究职业大厅的升级选项。"}}
D.ClientTexts.Currency[1226]={Name={["058e609dec9a1ca6:11"]=S[18705]},Description={["e11bba720af66825:57"]="虚空的结晶碎片，由燃烧军团带到艾泽拉斯。"}}
D.ClientTexts.Currency[1268]={Name={["1a20ea88cf30d873:16"]="上古神器"},Description={["8af5d9499e5d4e8c:97"]=S[302]}}
D.ClientTexts.Currency[1273]={Name={["ecef1a8081c43ab5:16"]="破碎命运印记"},Description={["6ca623a635075ab5:90"]="扭转命运，可给你一次在《军团再临》团队副本和史诗地下城的首领处获得额外宝物的机会。"}}
D.ClientTexts.Currency[1275]={Name={["9747f1b854bfd9b5:11"]="古怪硬币"},Description={["5df4fad51a60a862:98"]="这种特别的货币摸上去热乎乎的，并在你手中轻轻震动着。可以用来向达拉然的苏伊奥斯购买物品。"}}
D.ClientTexts.Currency[1299]={Name={["0a02fcd408d6699f:13"]="拳手的金币"},Description={["58892a6e039b8efb:122"]="搏击俱乐部的获胜者得到的奖励。可以用它在拳手金币兑换商处购买乱斗卡牌和其他能够改变世界的物品。"}}
D.ClientTexts.Currency[1314]={Name={["f3d7d8bbb2d080e2:21"]="徘徊之魂碎片"},Description={["ecc33f3a23b774a5:42"]="曾属于某个强大敌人的灵魂残片。"}}
D.ClientTexts.Currency[1324]={Name={["e128e375ca541358:23"]="部落其拉嘉奖令"},Description={["ae5adf72f3674c3f:160"]="完成此任务可增加部落在甲虫的召唤活动中的积分。\r\n\r\n活动中积分最高的阵营可以将自己的旗帜挂在甲虫之锣旁，直到年末。"}}
D.ClientTexts.Currency[1325]={Name={["337461bce6a1f683:26"]="联盟其拉嘉奖令"},Description={["cb951cd908359b94:163"]="完成此任务可增加联盟在甲虫的召唤活动中的积分。\r\n\r\n活动中积分最高的阵营可以将自己的旗帜挂在甲虫之锣旁，直到年末。"}}
D.ClientTexts.Currency[1342]={Name={["3e1a804183652720:21"]="抗魔联军战争物资"},Description={["30887a7856d2e00d:65"]="用于强化破碎海滩上的珍贵建筑。"}}
D.ClientTexts.Currency[1355]={Name={["e617948246fceb43:10"]="邪能精华"},Description={["aab492672141c6f2:77"]="浓缩的恶魔精华，可收集并用于制造强大的护甲。"}}
D.ClientTexts.Currency[1356]={Name={["c895dfed7266dfc2:14"]="战斗的回响"},Description={["f190695343e9daf0:78"]="用于购买强大的PvP护甲。赛季结束时，此货币会转换为金币。"}}
D.ClientTexts.Currency[1357]={Name={["862748e356eaff38:18"]="主宰的回响"},Description={["c776483235f6d5f9:75"]="用于购买精锐PvP护甲。赛季结束时，此货币会转换为金币。"}}
D.ClientTexts.Currency[1379]={Name={["67acb288fd5a13b5:17"]="时尚试炼奖币"},Description={["8d357194463b3217:91"]="通过参与时尚试炼获得。可以在绝大多数主城兑换可幻化的装备。"}}
D.ClientTexts.Currency[1416]={Name={["5692e33228bbea91:10"]="空气硬币"},Description={["cf1b513d51ac9a0e:29"]="旋即蒸发，化为迷雾。"}}
D.ClientTexts.Currency[1501]={Name={["037df257a3d729b0:15"]="沸腾的精华"},Description={["a52142d4c2f14e2f:48"]="用于将《军团再临》传说物品的物品等级提升至970。"}}
D.ClientTexts.Currency[1506]={Name={["41733b61bc60346a:13"]="阿古斯道标石"},Description={["fb7ac3aa1c64d11d:84"]="萨格拉斯的仆从用它来强行打开从阿古斯前往其他被军团控制的世界的传送门。"}}
D.ClientTexts.Currency[1508]={Name={["e15bd71de09db3fc:14"]="黯淡的阿古尼特水晶"},Description={["d52e4f444eaa0123:103"]="这种没有光泽的水晶是虚灵商人眼中的极品，对维迪卡尔上的魔术师瓦西里恩来说更是如此。"}}
D.ClientTexts.Currency[1533]={Name={["f4e1f87f455c4458:15"]="觉醒精华"},Description={["2418c08c603c150b:91"]="供破碎群岛上方的达拉然的奥法工匠维迪尔使用，他可以制造或升级《军团再临》传说物品。"}}
D.ClientTextIndex.Currency.Description={}
