D.ClientTexts.BattlePet[39]={Description={["968181322f54c8e9:85"]="机械松鼠体内的逻辑运算中心告诉它，要多多采集坚果和螺栓，以备冬季取用。"},Source={["f18900d2ac976b15:22"]=S[679]}}
D.ClientTexts.BattlePet[40]={Description={["70fcfb3ce4370bab:103"]="冬妮·安萨妮娅计划在她临终时找一只灰猫陪葬，聪明的冒险者此刻又能大展身手了。"}}
D.ClientTexts.BattlePet[41]={Description={["f73cd700719e7509:105"]="冬妮·安萨妮娅邀请这些猫来她的午后茶会，但她没有提供它们最爱的饮品：敌人的眼泪。"}}
D.ClientTexts.BattlePet[42]={Description={["f5b08e8d6c9dd610:52"]="老奥特兰克俗语说：‘猫有九命，但却只需要其中之一。’"},Source={["56aef63090e67b57:37"]="掉落：世界掉落\n地区：希尔斯布莱德丘陵"}}
D.ClientTexts.BattlePet[43]={Description={["aa7b63cac4b0161d:105"]="上一个想要驯服这只猫的家伙很快意识到，地毯上有点污渍，总比整张地毯被撕成碎片来的强。"}}
D.ClientTexts.BattlePet[44]={Description={["d5b564a476f43c5b:58"]="它漂亮的蓝眼睛闻名遐迩，同时也被大鱼人视为美味佳肴。"}}
D.ClientTexts.BattlePet[45]={Description={["8575d069dc5be2d4:60"]="睡懒觉是这只猫的第二大嗜好。第一大嗜好是打哈欠。"}}
D.ClientTexts.BattlePet[46]={Description={["88680262b9408251:123"]="‘皇后有三只猫。第一只猫给她抓来了肥硕的老鼠；第二只猫给她弄来了美味的野兔；而最后那只她最爱的白猫，给她送上了仇敌的头颅。’"}}
D.ClientTexts.BattlePet[47]={Description={["ce5e2ac3fede3d94:77"]="有人说这只聪明的鸟能学会说话——但它很机灵，知道什么叫沉默是金。"}}
D.ClientTexts.BattlePet[49]={Description={["4a070c672eaedd26:93"]="丛林巨魔训练这些鸟儿模仿呼救声，引诱那些无知的旅行者并将他们引入陷阱。"},Source={["972c826877360a85:63"]=S[12338]}}
D.ClientTexts.BattlePet[50]={Description={["79df622d150bee8e:107"]="这种五彩缤纷的小鸟是迪菲亚海盗喜爱的宠物，擅长记忆口令，购物清单和爆竹配方。"},Source={["f4ca14264152557f:34"]="掉落：迪菲亚海盗\n地区：死亡矿井"}}
D.ClientTexts.BattlePet[51]={Description={["d8caa30082c24875:119"]="深受藏宝海湾地精们所喜爱的一个宠物，这只色彩艳丽的小鸟不仅会数钱，还会讨价还价，而且撒谎从不脸红。"}}
D.ClientTexts.BattlePet[52]={Description={["eb4f6c2bf698a2f4:31"]="在它看来，你吃上去也像鸡肉。"}}
D.ClientTexts.BattlePet[55]={Description={["1aab99577666c714:95"]="这只蟑螂通常是冲动消费的产物。购买者总是使劲浑身解数也难以摆脱它。"}}
D.ClientTexts.BattlePet[56]={Description={["791837525d414749:59"]="但愿有一天，它能长成像它母亲那样能够攻城拔寨的巨龙。"},Source={["a63d21b08c31185f:68"]="掉落：各色雏龙\n地区：湿地、尘泥沼泽、荒芜之地、燃烧平原"}}
D.ClientTexts.BattlePet[57]={Description={["4ac326cd750b15e2:97"]="和蓝龙军团的其他成员一样，这些古怪的小龙展现出了对奥术魔法的非凡亲和力。"},Source={["3705581341010c6a:31"]="掉落：世界掉落\n地区：冬泉谷"}}
D.ClientTexts.BattlePet[58]={Description={["52e6b44b8bea7b10:105"]="这头小龙来自湿地，还在学习捕猎、喷火并不断可爱地发着毁灭性脾气。"},Source={["8f27a6690d52eaba:27"]="掉落：世界掉落\n地区：湿地"}}
D.ClientTexts.BattlePet[59]={Description={["b1fe0e9284ce2535:97"]="这种独特的雏龙曾由绿龙伊萨里奥斯孵化并抚育，已经在菲拉斯的丛林中安居了下来。"},Source={["ce82743d32498faa:29"]="掉落：毒性雏龙\n地区：菲拉斯"}}
D.ClientTexts.BattlePet[64]={Description={["842d4f747cf518f5:76"]="暗月马戏团的商贩经常卖一些稀奇古怪的东西，林蛙就是其中之一。"}}
D.ClientTexts.BattlePet[65]={Description={["daa2553a2fec2ff9:41"]="它们以强劲的腿脚和敏锐的视力著称于世。"}}
D.ClientTexts.BattlePet[67]={Description={["df68889751201478:86"]="在泰达希尔的德鲁伊中，这种黑色羽毛的猛禽经常被视为是末日来临的先兆。"}}
D.ClientTexts.BattlePet[68]={Description={["29607b199e245df2:75"]="暗夜精灵的孩子在他们第一次生日时都会得到一根猫头鹰的羽毛，它象征着好运常伴。"}}
D.ClientTexts.BattlePet[69]={Description={["63dd9b4ee935a8b9:93"]="冬泉谷的熊怪很珍视这些美丽生物的雪白羽毛，并将其用于举行仪式。"},Source={["1ff3ff2c70dae007:35"]="宠物对战：冬泉谷\n季节：冬季"}}
D.ClientTexts.BattlePet[70]={Description={["840277cdb29fb690:75"]="一个相当复杂的地道系统保护了土拨鼠免遭邻居的大蹄子踩踏。"}}
D.ClientTexts.BattlePet[72]={Description={["4284b468c8614e61:55"]="要是你一直追逐雪兔，那你就离摔跟头不远了。"}}
D.ClientTexts.BattlePet[74]={Description={["1d9daa879db53668:105"]="肯瑞托法师最钟爱的小伙伴之一。这个爬来爬去的小家伙最让人困惑的是——它究竟算是蛇呢，还是其他什么。"}}
D.ClientTexts.BattlePet[75]={Description={["0dd57a2be0f71aec:94"]="克萨迪斯大胆地追踪、捕获并驯服那些大蟒蛇，以便它们能在战斗中呼朋唤友。"}}
D.ClientTexts.BattlePet[77]={Description={["161499d95e549954:100"]="这些棕色蟒蛇原产于部落控制的地区。它看上去并不显眼，直到猎物走进其攻击范围。"}}
D.ClientTexts.BattlePet[78]={Description={["a89c11b2e4c28997:101"]="这条赤练蛇深受暗矛巨魔的喜爱，不仅是因为它超强的毒性，还因为它不变的忠诚。"}}
D.ClientTexts.BattlePet[83]={Description={["4d864b2edf29d2ef:99"]="别担心，我想这个单位的战斗机制和归返逻辑都已被禁用了。——奥格索普·奥布诺提斯"},Source={["73e18dcd54a3e3f8:33"]="任务：你自己的OOX\n地区：藏宝海湾\n"}}
D.ClientTexts.BattlePet[84]={Description={["8cc704983cf3c607:51"]="别管这只鸟叫小鸡，除非你想让自己的脸被鸡蛋砸开花。"},Source={["f2332c9cb22177b3:25"]="任务：咕咕嘎！\n地区：西部荒野"}}
D.ClientTexts.BattlePet[85]={Description={["8a01e0cab11d1327:59"]="也许易爆，绝对可爱。远离明火。"},Source={["f18900d2ac976b15:22"]=S[679]}}
D.ClientTexts.BattlePet[86]={Description={["17a5f5526de81b83:124"]="这个微小的维和安全机器人通常装备有最新式的施法者克星和群体打击者。不适用于环保人士。"},Source={["f18900d2ac976b15:22"]=S[679]}}
D.ClientTexts.BattlePet[87]={Description={["0c9e1c41f8b027d2:84"]="这些可爱的小家伙在经过一天的野蛮、血腥的战斗后，最喜欢和它们的主人依偎在一起。"},Source={["4c67aa65a64b2e98:26"]="掉落：世界掉落\n地区：菲拉斯"}}
D.ClientTexts.BattlePet[89]={Description={["adbc3805a8d48f64:70"]="座狼是兽人们喜爱的伙伴，并在战场上极其忠诚。"},Source={["e7f4060a50aa0c75:48"]="掉落：军需官兹格雷斯\n地区：黑石塔下层"}}
D.ClientTexts.BattlePet[90]={Description={["4e6fee23070434ae:94"]="虽然出生在温暖的黑石塔高层，但烟网小蜘蛛能够适应绝大部分环境。"},Source={["30de0925d91f5c16:45"]="掉落：烟网蛛后\n地区：黑石塔下层"}}
D.ClientTexts.BattlePet[92]={Description={["29da283fa7bc8ba8:96"]="这只迷你熊猫幼崽尽管天生嗜睡，却广受艾泽拉斯冒险者的追捧。"},Source={["96dffb0a234283cf:43"]=S[16497]}}
D.ClientTexts.BattlePet[93]={Description={["473fa7e9b89131ee:85"]="天穹将要震颤，凡人注定悲泣，而末日将会——等等，你怎么这么高？"},Source={["9b242363bc4116ee:42"]=S[16497]}}
D.ClientTexts.BattlePet[94]={Description={["ef7178729df0838b:93"]="异虫大军的成员，体型微小却凶猛善战，千万不要低估了跳虫的实力。如果成批来袭，是非常危险的。"},Source={["9b242363bc4116ee:42"]=S[16497]}}
D.ClientTexts.BattlePet[95]={Description={["1e3a298a425f179b:96"]="天赋异禀的工程师们制造出了林蛙的精密复制体——成本仅相当于真品价格的十倍。"},Source={["f18900d2ac976b15:22"]=S[679]}}
D.ClientTexts.BattlePet[106]={Description={["0695c2081978659b:102"]="许多人认为传说中的醉蛙已经灭绝了，直到暗月马戏团的怪味酒把它们都吸引了出来。"},Source={["89ba93cb2797c5d8:24"]="世界事件：暗月马戏团"}}
D.ClientTexts.BattlePet[107]={Description={["f4706778dca64701:68"]="这只可爱又隐居避世的鱼人，其外表一定能吸引大批围观者。"},Source={["fc4bf3b8c0943a1d:22"]="特殊：2005年暴雪嘉年华"}}
D.ClientTexts.BattlePet[111]={Description={["c31efcf7bea3c8f0:103"]="乐奇那可爱迷人的气质和活泼搞怪的动作，必然能舒缓沮丧，令最晦暗的心情焕发光亮。"},Source={["2048f37c59d11063:50"]="特殊：燃烧的远征典藏版（仅限欧洲）\n"}}
D.ClientTexts.BattlePet[114]={Description={["bc2da3f11bbc659a:89"]="警告：请在接触恶心的软泥怪时佩戴手套和护目镜。请勿水洗。可污染大部分护甲。"},Source={["a032d49a6d4c6dbd:43"]="掉落：世界掉落\n怪物：软泥怪和蠕虫类"}}
D.ClientTexts.BattlePet[115]={Description={["b527c55f86ab8862:110"]="出生后，新生的小鲨鱼会立即逃离它们饥饿的母亲。过早的独立使它们更加危险，即便是小鲨鱼"}}
D.ClientTexts.BattlePet[116]={Description={["5945fa7b1bdddfb6:122"]="在这个聪明小玩意的内部装有秘密开关，可禁用‘安静’模式。所幸就连制作它的工程师都不知道这个开关在哪儿。"},Source={["f18900d2ac976b15:22"]=S[679]}}
D.ClientTexts.BattlePet[117]={Description={["42a155d78cb3f646:97"]="他很爱和你跳舞，和你摇摆，和你嬉戏！他会在冬幕节之后融化。别担心，他还会再回来的！"},Source={["d00fbada955d933f:28"]="世界事件：冬幕节\n"}}
D.ClientTexts.BattlePet[118]={Description={["98c7c50616301d4d:59"]="等不及要打开包装精美的节日礼盒了。"},Source={["d00fbada955d933f:28"]=S[812]}}
D.ClientTexts.BattlePet[119]={Description={["2173325f533952d6:120"]="这些小家伙不知疲倦地在为冬幕节做精心准备，并且在接下来的日子中如果能不被打扰，他们就很感激了。"},Source={["d00fbada955d933f:28"]=S[812]}}
D.ClientTexts.BattlePet[120]={Description={["1a1a102cb2e09939:118"]="在宏大的冬幕节庆典期间，这些忠实的小伙伴将快乐传播至整个大陆。在接下来的日子里，她们可有的忙了。"},Source={["d00fbada955d933f:28"]=S[812]}}
D.ClientTexts.BattlePet[121]={Description={["a8e138d9df26d63e:96"]="咕唧生来就是个表演者，尽管她很少抛头露面，只在极为难得的场合才会公开亮相。"},Source={["f80825d1280833f0:28"]="特殊：欧洲Fansite活动\n"}}
D.ClientTexts.BattlePet[159]={Description={["871bf640c023b08f:96"]="德莱尼人以驯服的雷象为坐骑，在野外它们通常因为珍贵的象牙而被猎杀。"},Source={["eb109ad84f45d1f1:25"]=S[811]}}
D.ClientTexts.BattlePet[122]={Description={["65336016f7067a0f:88"]="爱情的力量也会成为危险的东西，特别是当一个轻浮且脾气暴躁的地精坠入爱河时。"}}
D.ClientTexts.BattlePet[124]={Description={["bdbfb6edbfcf519a:86"]="这只小家伙和它的同类有着许多相似之处，但其吟唱能力却自成一格。"},Source={["2eda4f11d7a36198:15"]="特殊：iCoke"}}
D.ClientTexts.BattlePet[125]={Description={["a1dc13528a0114eb:25"]="稳扎稳打才能赢得这场比赛。"},Source={["eb109ad84f45d1f1:25"]=S[811]}}
D.ClientTexts.BattlePet[126]={Description={["b208c427f5545d60:111"]="许多人相信‘扭扭’这名字取自于这头猪走路时屁股扭扭的样子，直到他们看到自己的时候才明白其中的真正含义。"},Source={["eb109ad84f45d1f1:25"]=S[811]}}
D.ClientTexts.BattlePet[127]={Description={["cc33477f8169d0e4:72"]="古灵精怪的吱吱能通过装死躲避捕食者和收藏家。"},Source={["eb109ad84f45d1f1:25"]=S[811]}}
D.ClientTexts.BattlePet[128]={Description={["ea5dbc9705530a1a:108"]="这一小块夏季元素散发着温暖夏夜和雷雨的气息。如果你凑近仔细看，或许能看清它的五官。"}}
D.ClientTexts.BattlePet[130]={Description={["b296fe82a7f46503:164"]="在鹰身人入侵菲拉斯之后，几个角鹰兽筑巢地遭到了攻击。数百只角鹰幼兽变成了孤儿，萨尔多岛上的德鲁伊们肩负起了抚养它们的责任。"},Source={["0e7020549fcd9ac7:31"]="集换式卡牌：艾泽拉斯英雄传"}}
D.ClientTexts.BattlePet[131]={Description={["262490b562fad92c:123"]="作为外域虚空幼龙的后代，这只幼龙仍在努力成长为空中猎手、保护者或是令人敬畏的恐怖力量。"},Source={["ce49facf7455affe:42"]="特殊：燃烧的远征典藏版"}}
D.ClientTexts.BattlePet[132]={Description={["a9d0ac8b43a2b370:68"]="只有神奇的愿望才能造就魔法龙虾。如果你想要钓到这种鱼，就得心怀愿望才行。"},Source={["7db4a13579bf587e:53"]="钓鱼：钓鱼（430）\n地区：泰罗卡森林（渔点）"}}
D.ClientTexts.BattlePet[136]={Description={["f9a4cdb879b78b93:104"]="自从了解到它们能以奥术能量为食后，虚灵拉沙德就开始喂养这些魔法生物了。"}}
D.ClientTexts.BattlePet[137]={Description={["edc672e59b5527a8:67"]="这只兔子的对手一定是头一次见到这么可爱的小东西。也是最后一次。"}}
D.ClientTexts.BattlePet[138]={Description={["d6115b7e7d5385ff:88"]="秘蓝岛的濒危物种，谣传这种散发着魔力的昆虫拥有治疗能力。"}}
D.ClientTexts.BattlePet[139]={Description={["928a725ebfec5f57:150"]="一种受到了原始魔法能量影响的产物。该昆虫原是艾泽拉斯的蛾类生物，引进至虚空风暴的生态圆顶后，其颜色变得异常艳丽。"}}
D.ClientTexts.BattlePet[140]={Description={["56c351569f85a3e7:63"]="它喜欢在暴风骤雨中飞行，这在秘蓝岛上是平常事。"}}
D.ClientTexts.BattlePet[141]={Description={["33105e1d21f0900a:61"]="它喜欢在多雾的夜间翱翔，这在秘蓝岛上是平常事。"}}
D.ClientTexts.BattlePet[142]={Description={["ed00095762fb6432:116"]="曾一度被银月城的龙鹰饲养员视为珍宝。由于夜间在捕食者眼中非常显眼，使得它在幼年时期就练出了极高的警惕性。"}}
D.ClientTexts.BattlePet[143]={Description={["f9de4d14854737cd:74"]="普通敌人只配有银色龙鹰，只有那些精英才配有金色龙鹰。"}}
D.ClientTexts.BattlePet[144]={Description={["c0d1ac55fc18d2a8:71"]="凶猛的龙鹰种类。经常能看到它从高空俯冲下来，进行掠食。"}}
D.ClientTexts.BattlePet[145]={Description={["5aa9a58caff8d75f:54"]="尽管鲜有人饲养，但商人们还是很愿意在虚空风暴进行交易。"}}
D.ClientTexts.BattlePet[146]={Description={["3b5b33f4166ccd9d:142"]="这种荧光昆虫通常被航行于赞加沼泽航道上的孢子人当成光源来使用，并帮助他们躲避危险的水光针刺者。"},Source={["e8edc7a9244a3598:36"]="掉落：水光针刺者\n地区：赞加沼泽"}}
D.ClientTexts.BattlePet[149]={Description={["b93b12a38255d6fa:166"]="天空之翼变回真实鸦人形态时所释放的魔法能量，解救了这只可怜的小动物——卢埃加囚禁了这只雏鸟，以强化他的禽鸟诅咒。"},Source={["ee9c3a89b8fd7df6:32"]="任务：天空之翼\n地区：泰罗卡森林\n\n"}}
D.ClientTexts.BattlePet[153]={Description={["7c73d602347cc617:98"]="许多在美酒节上喝的酩酊大醉的人都谈论过这个神秘生物，但极少数人在第二天早晨醒来还记得住。"},Source={["71e287ab0d9f5834:19"]="世界事件：美酒节"}}
D.ClientTexts.BattlePet[155]={Description={["45195f098fb93900:76"]="金猪在发怒或进食时都会尖叫。不论是上述哪种情形，最好都别去打搅他。"},Source={["a2535d5253c2d6b7:35"]="特殊：2007年暴雪全球邀请赛\n"}}
D.ClientTexts.BattlePet[156]={Description={["fb11dfac76d49c67:132"]="虽然万般不愿意与蕉蕉分离，兰德鲁还是意识到，等到他爸爸穆克拉发现他失踪时，这只宠物还是远离藏宝海湾的好。"},Source={["46bf5a52a0d0a7e5:36"]="集换式卡牌：穿越黑暗之门"}}
D.ClientTexts.BattlePet[157]={Description={["2299ae7289f981c7:64"]="他虽然有点坏坏的，但极度嗜睡。让他远离小动物！"},Source={["eb109ad84f45d1f1:25"]=S[811]}}
D.ClientTexts.BattlePet[158]={Description={["8fe108befbb147d9:114"]="辛多雷使用陆行鸟作为坐骑，但这个小家伙因为被诊断出患有多重焦虑症而被视为不符合要求的坐骑。"},Source={["eb109ad84f45d1f1:25"]=S[811]}}
D.ClientTexts.BattlePet[160]={Description={["70929d9c50bb3e5d:99"]="臭臭靠自己的臭味来吓退捕食者，并攻击猫咪。不过对于前者的成功率要远高于后者。"},Source={["315ea8992b3f4e98:56"]="成就：理智购物，理智购……宠物\n分类：宠物对战"}}
